// WWE '13: pin kick-out research (EXPERIMENTAL, off unless WWE13_AI_KICKOUT / WWE13_KICKOUT_LOG are set; no launcher option).
// Finding so far: the CPU does not use the timing meter below (its state stays 0); it escapes through its own logic,
// so shrinking the zone does not change CPU kick-outs. Kept for logging while the CPU decision is tracked down.
// Hand-written; not generated by ReXGlue.
//
// The pin escape is the game's timing meter: sub_82551668 builds it (r3 = meter, r4 = pinner, r5 = pinned wrestler) and
// sets the escape zone [lo, hi] on a 0-120 bar (meter +80 / +84) from the pinned wrestler's damage and the last big move
// (PFBD levels in misc.pac BATL/INIT 22). sub_82552050 updates it each frame: the needle (+96) runs, and a press inside
// the zone is a kick-out (+72 = 2), outside it a pinfall (+72 = 3). The CPU plays the same meter, so a smaller zone for a
// CPU-controlled wrestler means fewer CPU kick-outs; the player's meter, damage, reversals and the rest are unchanged.
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <string>
#include <cstdio>

#include <rex/logging.h>
#include "rex_compat.h"

namespace {
int Percent() {  // 100 = the game's own zone
  static const int p = [] {
    const char* e = std::getenv("WWE13_AI_KICKOUT");
    int v = e && *e ? std::atoi(e) : 100;
    if (v < 10) v = 10;
    if (v > 100) v = 100;
    if (v != 100) REXLOG_INFO("[wwe13-kickout] CPU kick-out zone {}% of normal", v);
    return v;
  }();
  return p;
}

bool LogOn() {
  static const bool on = [] { const char* e = std::getenv("WWE13_KICKOUT_LOG"); return e && *e == '1'; }();
  return on;
}

uint32_t Ctrl(uint8_t* base, uint32_t w) { return w ? PPC_LOAD_U32(w + 2788) : 0; }
uint32_t Vt(uint8_t* base, uint32_t o) { return o ? PPC_LOAD_U32(o) : 0; }
}  // namespace

extern "C" PPC_FUNC(__imp__sub_82551668);
extern "C" PPC_FUNC(sub_82551668) {
  const uint32_t meter = ctx.r3.u32, pinner = ctx.r4.u32, pinned = ctx.r5.u32;
  __imp__sub_82551668(ctx, base);
  if (!meter || !pinned) return;
  const int32_t lo = int32_t(PPC_LOAD_U32(meter + 80)), hi = int32_t(PPC_LOAD_U32(meter + 84));
  const uint32_t pc = Ctrl(base, pinned), rc = Ctrl(base, pinner);
  static const bool any = [] { const char* e = std::getenv("WWE13_KICKOUT_ANY"); return e && *e == '1'; }();
  const bool cpu = pc && PPC_LOAD_U32(pc + 0x48) == 1;  // controller +0x48: 1 = CPU-controlled (seen on pins)
  if (Percent() < 100 && (cpu || any) && hi > lo) {
    const int32_t w = hi - lo, nw = w * Percent() / 100 > 0 ? w * Percent() / 100 : 1, c = (lo + hi) / 2;
    PPC_STORE_U32(meter + 80, uint32_t(c - nw / 2));
    PPC_STORE_U32(meter + 84, uint32_t(c - nw / 2 + nw));
    if (LogOn()) REXLOG_INFO("[wwe13-kickout] cpu={} zone {}..{} -> {}..{}", cpu, lo, hi, c - nw / 2, c - nw / 2 + nw);
  }
  if (const char* dir = std::getenv("WWE13_KICKOUT_DUMP")) {  // wrestler structs, for finding the CPU flag
    static int n = 0;
    ++n;
    for (int k = 0; k < 2; ++k) {
      const uint32_t w = k ? pinner : pinned;
      if (!w) continue;
      const std::string path = fmt::format("{}/pin{:02}_{}.bin", dir, n, k ? "pinner" : "pinned");
      if (FILE* f = std::fopen(path.c_str(), "wb")) {
        std::fwrite(base + w, 1, 4096, f);
        const uint32_t c = Ctrl(base, w);
        if (c) std::fwrite(base + c, 1, 1024, f);
        std::fclose(f);
      }
    }
  }
  if (LogOn()) {
    std::string d;
    for (int i = 0; i < 24; ++i) d += fmt::format("{:08X} ", pc ? PPC_LOAD_U32(pc + 4 * i) : 0);
    REXLOG_INFO("[wwe13-kickout] pinned ctrl words: {}", d);
    d.clear();
    for (int i = 0; i < 24; ++i) d += fmt::format("{:08X} ", rc ? PPC_LOAD_U32(rc + 4 * i) : 0);
    REXLOG_INFO("[wwe13-kickout] pinner ctrl words: {}", d);
    REXLOG_INFO("[wwe13-kickout] pin: zone {}..{} level {} pinned w={:08X} ctrl={:08X} vt={:08X} b2165={} | pinner w={:08X} ctrl={:08X} vt={:08X}",
                lo, hi, PPC_LOAD_U8(pinned + 2240), pinned, pc, Vt(base, pc), PPC_LOAD_U8(pinned + 2165), pinner, rc, Vt(base, rc));
  }
}

extern "C" PPC_FUNC(__imp__sub_82552050);
extern "C" PPC_FUNC(sub_82552050) {
  const uint32_t meter = ctx.r3.u32;
  const uint32_t before = meter ? PPC_LOAD_U32(meter + 72) : 0;
  __imp__sub_82552050(ctx, base);
  if (!meter || !LogOn()) return;
  const uint32_t after = PPC_LOAD_U32(meter + 72);
  if (after != before) {
    float needle;
    const uint32_t nb = PPC_LOAD_U32(meter + 96);
    std::memcpy(&needle, &nb, 4);
    REXLOG_INFO("[wwe13-kickout] meter state {} -> {} needle {:.1f} zone {}..{}", before, after, needle,
                int32_t(PPC_LOAD_U32(meter + 80)), int32_t(PPC_LOAD_U32(meter + 84)));
  }
}

extern "C" PPC_FUNC(__imp__sub_82552578);
extern "C" PPC_FUNC(sub_82552578) {
  const uint32_t meter = ctx.r3.u32;
  const uint32_t before = meter ? PPC_LOAD_U32(meter + 72) : 0, b56 = meter ? PPC_LOAD_U32(meter + 56) : 0;
  __imp__sub_82552578(ctx, base);
  if (!meter || !LogOn()) return;
  const uint32_t after = PPC_LOAD_U32(meter + 72), a56 = PPC_LOAD_U32(meter + 56);
  if (after != before || a56 != b56) REXLOG_INFO("[wwe13-kickout] count: state {} -> {}, +56 {} -> {}", before, after, b56, a56);
}
